const due = $('Get Due Items').first().json;
const items = due.items || [];
const since = new Date(due.since).getTime();
const res = $input.first().json;
const apiOk = (res.statusCode || 200) < 400;
const all = ((res.body && res.body.data) || []).map(function (e) { const rd = (e.data && e.data.resultData) || {}; const er = rd.error || {}; return { workflow_id: e.workflowId, workflow: (e.workflowData && e.workflowData.name) || '', at: e.startedAt, node: rd.lastNodeExecuted || '', error: String(er.message || er.description || '').slice(0, 300) }; });
const errors = all.filter(function (e) { return new Date(e.at).getTime() >= since; });
const hard = {};
items.forEach(function (it) { errors.forEach(function (e) { if (new Date(e.at).getTime() < new Date(it.deleted_at).getTime()) return; const txt = (e.error + ' ' + e.node).toLowerCase(); if ((it.table !== 'workflow' && txt.indexOf(String(it.table).toLowerCase()) > -1) || (it.table === 'workflow' && e.workflow_id === it.row_id)) hard[it.id] = (hard[it.id] || []).concat([e.workflow + ': ' + e.error.slice(0, 120)]); }); });
const sys = 'You are the second-check agent (وكيل التحقق) of Al Mutawa Tourism system. Items were soft-deleted (or automations changed) 24+ hours ago. For each item decide if it is SAFE to purge permanently: safe unless an error that happened AFTER its deleted_at plausibly relates to it (same table/entity, its id, missing record, foreign key, null reference in a workflow that uses that data; for table=workflow: any error in that workflow id). Be strict but do not block on unrelated errors. Reply JSON only: {"verdicts":[{"id":<id>,"ok":true|false,"note":"short Arabic reason"}]}';
const user = JSON.stringify({ items: items, errors_since_first_delete: errors.slice(0, 60), error_api_available: apiOk });
return [{ json: { items, hard, apiOk, body: { model: 'gpt-5.5', response_format: { type: 'json_object' }, messages: [{ role: 'system', content: sys }, { role: 'user', content: user }] } } }];

const p = $('Build Review').first().json;
const r = $input.first().json;
let v = [];
try { const c = r.body.choices[0].message.content; v = JSON.parse(c).verdicts || []; } catch (e) { v = []; }
const map = {}; v.forEach(function (x) { map[String(x.id)] = x; });
const out = [];
if (p.apiOk && v.length) p.items.forEach(function (it) { const x = map[String(it.id)]; if (!x) return; const hard = p.hard[it.id]; const ok = !!x.ok && !hard; out.push({ id: it.id, ok: ok, note: (hard ? 'أخطاء مرتبطة: ' + hard.join(' | ') + '. ' : '') + String(x.note || '') }); });
return [{ json: { verdicts: JSON.stringify(out), checked: out.length, skipped: p.items.length - out.length } }];

const r = $input.first().json;
const d = $('Decide').first().json;
const f = Number(r.flagged || 0), pu = Number(r.purged || 0);
if (!f && !pu) return [{ json: { category: 'system', title: '🗑️ تعذر فحص سلة المحذوفات', body: 'وكيل التحقق ما قدر يراجع ' + d.skipped + ' عنصر هالمرة. بيعيد المحاولة الساعة الجاية.', priority: 'low' } }];
return [{ json: { category: 'system', title: f ? '⚠️ وكيل التحقق أوقف حذف ' + f + ' عنصر' : '🗑️ تم الحذف النهائي لـ ' + pu + ' عنصر بعد التحقق', body: r.lines + (f ? '\n\nالعناصر الموقوفة باقية في سلة المحذوفات ويقدر الوكيل يرجعها (database_restore).' : ''), priority: f ? 'high' : 'low' } }];

